#!/usr/bin/env python3
"""Add buffer-health-aware bandwidth prioritization to the 4.38 Reel controller."""
from pathlib import Path

OLD_DECL="var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true, memoryGb=Number(navigator.deviceMemory||4), networkType=String(conn.effectiveType||'').toLowerCase(), networkOnline=navigator.onLine!==false, networkValidated=true, networkMetered=false, downKbps=0, powerSaving=false, pressure=0, resumeTimer=0, lastScrollTop=0, scrollDirection=1, activeRatio=0, activateTimer=0, scrollRaf=0;"
NEW_DECL="var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true, memoryGb=Number(navigator.deviceMemory||4), networkType=String(conn.effectiveType||'').toLowerCase(), networkOnline=navigator.onLine!==false, networkValidated=true, networkMetered=false, downKbps=0, powerSaving=false, pressure=0, resumeTimer=0, lastScrollTop=0, scrollDirection=1, activeRatio=0, activateTimer=0, scrollRaf=0, bufferStarved=false, bufferTimer=0, bufferStableAt=0;"

OLD_BUDGET="function budget(){var i=cards.indexOf(active),constrained=conservative||powerSaving||networkMetered||!networkValidated,keepAhead=pressure>=10||powerSaving?0:(fastNetwork&&memoryGb>=4?2:1),direction=scrollDirection>=0?1:-1;cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!networkOnline||!networkValidated){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i,forward=distance*direction;if(distance===0)attach(st,'auto','high');else if(forward===1)attach(st,constrained?'metadata':'auto',constrained?'low':'high');else if(forward===-1)attach(st,'metadata','low');else if(forward>1&&forward<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}"
NEW_BUDGET="function budget(){var i=cards.indexOf(active),constrained=conservative||powerSaving||networkMetered||!networkValidated,keepAhead=pressure>=10||powerSaving?0:(fastNetwork&&memoryGb>=4?2:1),direction=scrollDirection>=0?1:-1,starved=bufferStarved;cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!networkOnline||!networkValidated){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i,forward=distance*direction;if(distance===0)attach(st,'auto','high');else if(forward===1)attach(st,(constrained||starved)?'metadata':'auto',(constrained||starved)?'low':'high');else if(forward===-1)attach(st,'metadata','low');else if(!starved&&forward>1&&forward<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,starved?180:releaseDelay);});}"

OLD_ACTIVATE="function activate(card){if(!card||!states.has(card)||!isReels())return;if(active===card){activeRatio=Math.max(activeRatio,.6);budget();return;}clearTimeout(activateTimer);pauseAll();if(active)active.removeAttribute('data-mm46-active');active=card;activeRatio=1;card.dataset.mm46Active='1';var st=states.get(card);budget();start(st,false);}"
NEW_ACTIVATE="function activate(card){if(!card||!states.has(card)||!isReels())return;if(active===card){activeRatio=Math.max(activeRatio,.6);budget();return;}clearTimeout(activateTimer);setStarved(false);pauseAll();if(active)active.removeAttribute('data-mm46-active');active=card;activeRatio=1;card.dataset.mm46Active='1';var st=states.get(card);budget();start(st,false);}"

OLD_REFRESH="function refreshMode(){var on=isReels();H.toggleAttribute('data-mm46-reels',on);dimensions();if(on){lastScrollTop=feed.scrollTop||0;panel.open=true;refreshCards();if(active&&!blocked())start(states.get(active),false);}else{clearTimeout(activateTimer);delete H.dataset.mm438Scrolling;pauseAll();cards.forEach(function(c){var st=states.get(c);if(c===active)attach(st,'metadata','low');else scheduleRelease(st,300);});} }"
NEW_REFRESH="function refreshMode(){var on=isReels();H.toggleAttribute('data-mm46-reels',on);dimensions();if(on){lastScrollTop=feed.scrollTop||0;panel.open=true;refreshCards();if(active&&!blocked())start(states.get(active),false);}else{clearTimeout(activateTimer);clearTimeout(bufferTimer);setStarved(false);delete H.dataset.mm438Scrolling;pauseAll();cards.forEach(function(c){var st=states.get(c);if(c===active)attach(st,'metadata','low');else scheduleRelease(st,300);});} }"

OLD_PLAYING="v.addEventListener('playing',function(){clearTimeout(st.waitTimer);clearStall(st);card.removeAttribute('data-mm46-loading');card.removeAttribute('data-mm433-slow');card.dataset.mm46Playing='1';if(typeof v.requestVideoFrameCallback==='function')v.requestVideoFrameCallback(function(){card.dataset.mm435Frame='1';});else card.dataset.mm435Frame='1';budget();});"
NEW_PLAYING="v.addEventListener('playing',function(){clearTimeout(st.waitTimer);clearStall(st);card.removeAttribute('data-mm46-loading');card.removeAttribute('data-mm433-slow');card.dataset.mm46Playing='1';if(typeof v.requestVideoFrameCallback==='function')v.requestVideoFrameCallback(function(){card.dataset.mm435Frame='1';});else card.dataset.mm435Frame='1';probeBuffer(st,true);scheduleBufferProbe(st);budget();});"

OLD_WAITING="v.addEventListener('waiting',function(){clearTimeout(st.waitTimer);st.waitTimer=setTimeout(function(){if(active===card&&!v.paused&&!blocked())card.dataset.mm46Loading='1';},240);scheduleStall(st);});\n v.addEventListener('stalled',function(){scheduleStall(st);});"
NEW_WAITING="v.addEventListener('waiting',function(){clearTimeout(st.waitTimer);setStarved(true);st.waitTimer=setTimeout(function(){if(active===card&&!v.paused&&!blocked())card.dataset.mm46Loading='1';},240);scheduleStall(st);scheduleBufferProbe(st);});\n v.addEventListener('stalled',function(){setStarved(true);scheduleStall(st);scheduleBufferProbe(st);});\n v.addEventListener('progress',function(){if(active===card){probeBuffer(st,false);scheduleBufferProbe(st);}});"

OLD_TIMEUPDATE="v.addEventListener('timeupdate',function(){clearStall(st);if(Number.isFinite(v.currentTime)&&v.currentTime>st.lastProgressTime+8){st.lastProgressTime=v.currentTime;st.recoveryCount=0;}if(active!==card||!Number.isFinite(v.duration)||v.duration<=0)return;seeker.value=String(Math.round(1000*v.currentTime/v.duration));seeker.setAttribute('aria-valuetext',Math.floor(v.currentTime)+' dari '+Math.floor(v.duration)+' detik');});"
NEW_TIMEUPDATE="v.addEventListener('timeupdate',function(){clearStall(st);if(Number.isFinite(v.currentTime)&&v.currentTime>st.lastProgressTime+8){st.lastProgressTime=v.currentTime;st.recoveryCount=0;}if(active===card)scheduleBufferProbe(st);if(active!==card||!Number.isFinite(v.duration)||v.duration<=0)return;seeker.value=String(Math.round(1000*v.currentTime/v.duration));seeker.setAttribute('aria-valuetext',Math.floor(v.currentTime)+' dari '+Math.floor(v.duration)+' detik');});"

OLD_DESTROY="function destroy(){disposed=true;clearTimeout(resumeTimer);clearTimeout(activateTimer);clearTimeout(scrollTimer);if(scrollRaf)cancelAnimationFrame(scrollRaf);delete H.dataset.mm438Scrolling;pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();if('onscrollend' in feed)feed.removeEventListener('scrollend',settleScroll);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('mmapp:runtime',runtimeChanged);window.removeEventListener('mmapp:network',runtimeChanged);window.removeEventListener('mmapp:power',powerChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"
NEW_DESTROY="function destroy(){disposed=true;clearTimeout(resumeTimer);clearTimeout(activateTimer);clearTimeout(scrollTimer);clearTimeout(bufferTimer);bufferStarved=false;H.removeAttribute('data-mm439-buffer-starved');if(scrollRaf)cancelAnimationFrame(scrollRaf);delete H.dataset.mm438Scrolling;pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();if('onscrollend' in feed)feed.removeEventListener('scrollend',settleScroll);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('mmapp:runtime',runtimeChanged);window.removeEventListener('mmapp:network',runtimeChanged);window.removeEventListener('mmapp:power',powerChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"

BUFFER_ANCHOR="function clearStall(st){"
BUFFER_FUNCTIONS="""function bufferAhead(v){try{if(!v||!v.buffered||!v.buffered.length||!Number.isFinite(v.currentTime))return 0;var now=v.currentTime;for(var i=0;i<v.buffered.length;i++){var start=v.buffered.start(i),end=v.buffered.end(i);if(start<=now+.15&&end>=now)return Math.max(0,end-now);}}catch(ignore){}return 0;}
function setStarved(value){var next=!!value;if(next===bufferStarved)return;bufferStarved=next;H.toggleAttribute('data-mm439-buffer-starved',next);if(!next)bufferStableAt=Date.now();budget();}
function probeBuffer(st,force){if(!st||active!==st.card||st.v.paused||blocked()||!networkOnline||!networkValidated)return;var ahead=bufferAhead(st.v);if(ahead<.75){setStarved(true);return;}if(ahead>3.25){if(force||Date.now()-bufferStableAt>450)setStarved(false);return;}if(force&&ahead<1.25)setStarved(true);}
function scheduleBufferProbe(st){clearTimeout(bufferTimer);if(!st||active!==st.card||st.v.paused)return;bufferTimer=setTimeout(function(){bufferTimer=0;probeBuffer(st,false);if(active===st.card&&!st.v.paused)scheduleBufferProbe(st);},bufferStarved?500:1200);}
"""

REPLACEMENTS=[
    (OLD_DECL,NEW_DECL),(OLD_BUDGET,NEW_BUDGET),(OLD_ACTIVATE,NEW_ACTIVATE),
    (OLD_REFRESH,NEW_REFRESH),(OLD_PLAYING,NEW_PLAYING),(OLD_WAITING,NEW_WAITING),
    (OLD_TIMEUPDATE,NEW_TIMEUPDATE),(OLD_DESTROY,NEW_DESTROY),
]

def patch_controller(path:Path)->None:
    text=path.read_text(encoding='utf-8')
    count=text.count(BUFFER_ANCHOR)
    assert count==1,f'{path}: expected one buffer anchor, found {count}'
    text=text.replace(BUFFER_ANCHOR,BUFFER_FUNCTIONS+BUFFER_ANCHOR,1)
    for old,new in REPLACEMENTS:
        count=text.count(old)
        assert count==1,f'{path}: expected one 4.38 anchor, found {count}: {old[:120]!r}'
        text=text.replace(old,new,1)
    path.write_text(text,encoding='utf-8')
